#
# Django module to support postgresql.org community authentication 2.0
#
# The main location for this module is the pgweb git repository hosted
# on git.postgresql.org - look there for updates.
#
# To integrate with django, you need the following:
# * Make sure the view "login" from this module is used for login
# * Map an url somwehere (typically /auth_receive/) to the auth_receive
#   view.
# * To get notified when a user is created from upstream, connect to the signal
#   auth_user_created_from_upstream.
# * To receive live updates (not just during login), map an url somewhere
#   (typically /auth_api/) to the auth_api view.
# * To receive live updates, also connect to the signal auth_user_data_received.
#   This signal will fire *both* on login events *and* on background updates.
# * In settings.py, set AUTHENTICATION_BACKENDS to point to the class
#   AuthBackend in this module.
# * (And of course, register for a crypto key with the main authentication
#   provider website)
# * If the application uses the django admin interface, the login screen
#   has to be replaced with something similar to login.html in this
#   directory (adjust urls, and name it admin/login.html in any template
#   directory that's processed before the default django.contrib.admin)
#

from django.http import HttpResponse, HttpResponseRedirect
from django.views.decorators.csrf import csrf_exempt
from django.contrib.auth.models import User
from django.contrib.auth.backends import ModelBackend
from django.contrib.auth import login as django_login
from django.contrib.auth import logout as django_logout
from django.dispatch import Signal
from django.db import transaction
from django.conf import settings

import base64
import json
import socket
import hmac
from urllib.parse import urlencode, parse_qs
import requests
from Cryptodome.Cipher import AES
from Cryptodome.Hash import SHA256
from Cryptodome import Random
import time


# This signal fires when a user is created based on data from upstream.
auth_user_created_from_upstream = Signal()

# This signal fires whenever new user data has been received. Note that this
# happens *after* first_name, last_name and email has been updated on the user
# record, so those are not included in the userdata struct.
auth_user_data_received = Signal()


class AuthBackend(ModelBackend):
    # We declare a fake backend that always fails direct authentication -
    # since we should never be using direct authentication in the first place!
    def authenticate(self, username=None, password=None):
        raise Exception("Direct authentication not supported")


####
# Two regular django views to interact with the login system
####

# Handle login requests by sending them off to the main site
def login(request):
    if 'next' in request.GET:
        # Put together an url-encoded dict of parameters we're getting back,
        # including a small nonce at the beginning to make sure it doesn't
        # encrypt the same way every time.
        s = "t=%s&%s" % (int(time.time()), urlencode({'r': request.GET['next']}))
        # Now encrypt it
        r = Random.new()
        nonce = r.read(16)
        encryptor = AES.new(
            SHA256.new(settings.SECRET_KEY.encode('ascii')).digest()[:32], AES.MODE_SIV, nonce=nonce
        )
        cipher, tag = encryptor.encrypt_and_digest(s.encode('ascii'))

        return HttpResponseRedirect("%s?%s" % (settings.PGAUTH_REDIRECT, urlencode({
            'd': '$'.join((
                base64.urlsafe_b64encode(nonce).decode('utf8'),
                base64.urlsafe_b64encode(cipher).decode('utf8'),
                base64.urlsafe_b64encode(tag).decode('utf8'),
            )),
        })))
    else:
        return HttpResponseRedirect(settings.PGAUTH_REDIRECT)


# Handle logout requests by logging out of this site and then
# redirecting to log out from the main site as well.
def logout(request):
    if request.user.is_authenticated:
        django_logout(request)
    return HttpResponseRedirect("%slogout/" % settings.PGAUTH_REDIRECT)


# Receive an authentication response from the main website and try
# to log the user in.
def auth_receive(request):
    if 's' in request.GET and request.GET['s'] == "logout":
        # This was a logout request
        return HttpResponseRedirect('/')

    if 'n' not in request.GET:
        return HttpResponse("Missing nonce in url!", status=400)
    if 'd' not in request.GET:
        return HttpResponse("Missing data in url!", status=400)
    if 't' not in request.GET:
        return HttpResponse("Missing tag in url!", status=400)

    # Set up an AES object and decrypt the data we received
    try:
        decryptor = AES.new(
            base64.b64decode(settings.PGAUTH_KEY),
            AES.MODE_SIV,
            nonce=base64.urlsafe_b64decode(str(request.GET['n'])),
        )
        s = decryptor.decrypt_and_verify(
            base64.urlsafe_b64decode(str(request.GET['d'])),
            base64.urlsafe_b64decode(str(request.GET['t'])),
        ).rstrip(b' ').decode('utf8')
    except UnicodeDecodeError:
        return HttpResponse("Badly encoded data found", 400)
    except Exception:
        return HttpResponse("Could not decrypt data", status=400)

    # Now un-urlencode it
    try:
        data = parse_qs(s, strict_parsing=True)
    except ValueError:
        return HttpResponse("Invalid encrypted data received.", status=400)

    # Check the timestamp in the authentication
    if (int(data['t'][0]) < time.time() - 10):
        return HttpResponse("Authentication token too old.", status=400)

    # Update the user record (if any)
    try:
        user = User.objects.get(username=data['u'][0])
        # User found, let's see if any important fields have changed
        changed = []
        if user.first_name != data['f'][0]:
            user.first_name = data['f'][0]
            changed.append('first_name')
        if user.last_name != data['l'][0]:
            user.last_name = data['l'][0]
            changed.append('last_name')
        if user.email != data['e'][0]:
            user.email = data['e'][0]
            changed.append('email')
        if changed:
            user.save(update_fields=changed)
    except User.DoesNotExist:
        # User not found, create it!

        # NOTE! We have some legacy users where there is a user in
        # the database with a different userid. Instead of trying to
        # somehow fix that live, give a proper error message and
        # have somebody look at it manually.
        if User.objects.filter(email=data['e'][0]).exists():
            return HttpResponse("""A user with email %s already exists, but with
a different username than %s.

This is almost certainly caused by some legacy data in our database.
Please send an email to webmaster@postgresql.org, indicating the username
and email address from above, and we'll manually merge the two accounts
for you.

We apologize for the inconvenience.
""" % (data['e'][0], data['u'][0]), content_type='text/plain')

        if getattr(settings, 'PGAUTH_CREATEUSER_CALLBACK', None):
            res = getattr(settings, 'PGAUTH_CREATEUSER_CALLBACK')(
                data['u'][0],
                data['e'][0],
                ['f'][0],
                data['l'][0],
            )
            # If anything is returned, we'll return that as our result.
            # If None is returned, it means go ahead and create the user.
            if res:
                return res

        user = User(username=data['u'][0],
                    first_name=data['f'][0],
                    last_name=data['l'][0],
                    email=data['e'][0],
                    password='[REDACTED]',
                    )
        user.save()

        auth_user_created_from_upstream.send(sender=auth_receive, user=user)

    # Ok, we have a proper user record. Now tell django that
    # we're authenticated so it persists it in the session. Before
    # we do that, we have to annotate it with the backend information.
    user.backend = "%s.%s" % (AuthBackend.__module__, AuthBackend.__name__)
    django_login(request, user)

    # Signal that we have information about this user
    auth_user_data_received.send(sender=auth_receive, user=user, userdata={
        'secondaryemails': data['se'][0].split(',') if 'se' in data else []
    })

    # Finally, check of we have a data package that tells us where to
    # redirect the user.
    if 'd' in data:
        splitdata = data['d'][0].split('$')
        if len(splitdata) != 3:
            return HttpResponse("Invalid login pass-through data received, likely because of an old link. Please try again.")
        (nonces, datas, tags) = splitdata
        decryptor = AES.new(
            SHA256.new(settings.SECRET_KEY.encode('ascii')).digest()[:32],
            AES.MODE_SIV,
            nonce=base64.urlsafe_b64decode(nonces),
        )
        s = decryptor.decrypt_and_verify(
            base64.urlsafe_b64decode(datas),
            base64.urlsafe_b64decode(tags),
        ).rstrip(b' ').decode('utf8')
        try:
            rdata = parse_qs(s, strict_parsing=True)
        except ValueError:
            return HttpResponse("Invalid encrypted data received.", status=400)
        if 'r' in rdata:
            # Redirect address
            return HttpResponseRedirect(rdata['r'][0])
    # No redirect specified, see if we have it in our settings
    if hasattr(settings, 'PGAUTH_REDIRECT_SUCCESS'):
        return HttpResponseRedirect(settings.PGAUTH_REDIRECT_SUCCESS)
    return HttpResponse("Authentication successful, but don't know where to redirect!", status=500)


# Receive API calls from upstream, such as push changes to users
@csrf_exempt
def auth_api(request):
    if 'X-pgauth-sig' not in request.headers:
        return HttpResponse("Missing signature header!", status=400)

    try:
        sig = base64.b64decode(request.headers['X-pgauth-sig'])
    except Exception:
        return HttpResponse("Invalid signature header!", status=400)

    try:
        h = hmac.digest(
            base64.b64decode(settings.PGAUTH_KEY),
            msg=request.body,
            digest='sha512',
        )
        if not hmac.compare_digest(h, sig):
            return HttpResponse("Invalid signature!", status=401)
    except Exception:
        return HttpResponse("Unable to compute hmac", status=400)

    try:
        pushstruct = json.loads(request.body)
    except Exception:
        return HttpResponse("Invalid JSON!", status=400)

    def _conditionally_update_record(rectype, recordkey, structkey, fieldmap, struct):
        try:
            obj = rectype.objects.get(**{recordkey: struct[structkey]})
            ufields = []
            for k, v in fieldmap.items():
                if struct[k] != getattr(obj, v):
                    setattr(obj, v, struct[k])
                    ufields.append(v)
            if ufields:
                obj.save(update_fields=ufields)
            return obj
        except rectype.DoesNotExist:
            # If the record doesn't exist, we just ignore it
            return None

    # Process the received structure
    if pushstruct.get('type', None) == 'update':
        # Process updates!
        with transaction.atomic():
            for u in pushstruct.get('users', []):
                user = _conditionally_update_record(
                    User,
                    'username', 'username',
                    {
                        'firstname': 'first_name',
                        'lastname': 'last_name',
                        'email': 'email',
                    },
                    u,
                )

                # Signal that we have information about this user (only if it exists)
                if user:
                    auth_user_data_received.send(sender=auth_api, user=user, userdata={
                        k: u[k] for k in u.keys() if k not in ['firstname', 'lastname', 'email', ]
                    })

    return HttpResponse("OK", status=200)


# Perform a search in the central system. Note that the results are returned as an
# array of dicts, and *not* as User objects. To be able to for example reference the
# user through a ForeignKey, a User object must be materialized locally. We don't do
# that here, as this search might potentially return a lot of unrelated users since
# it's a wildcard match.
# Unlike the authentication, searching does not involve the browser - we just make
# a direct http call.
def user_search(searchterm=None, userid=None):
    # If upstream isn't responding quickly, it's not going to respond at all, and
    # 10 seconds is already quite long.
    socket.setdefaulttimeout(10)
    if userid:
        q = {'u': userid}
    else:
        q = {'s': searchterm}

    r = requests.get(
        '{0}search/'.format(settings.PGAUTH_REDIRECT),
        params=q,
        timeout=10,
    )
    if r.status_code != 200:
        return []

    (nonces, datas, tags) = r.text.encode('utf8').split(b'&')

    # Decryption time
    decryptor = AES.new(
        base64.b64decode(settings.PGAUTH_KEY),
        AES.MODE_SIV,
        nonce=base64.urlsafe_b64decode(nonces)
    )
    s = decryptor.decrypt_and_verify(
        base64.urlsafe_b64decode(datas),
        base64.urlsafe_b64decode(tags),
    ).rstrip(b' ').decode('utf8')

    j = json.loads(s)

    return j


# Subscribe to any changes about this user on the community auth upstream
def subscribe_to_user_changes(userid):
    socket.setdefaulttimeout(10)

    body = json.dumps({
        'u': userid,
    })

    h = hmac.digest(
        base64.b64decode(settings.PGAUTH_KEY),
        msg=bytes(body, 'utf-8'),
        digest='sha512',
    )

    # Ignore the result code, just post it
    requests.post(
        '{0}subscribe/'.format(settings.PGAUTH_REDIRECT),
        data=body,
        headers={
            'X-pgauth-sig': base64.b64encode(h),
        },
    )


# Import a user into the local authentication system. Will initially
# make a search for it, and if anything other than one entry is returned
# the import will fail.
# Import is only supported based on userid - so a search should normally
# be done first. This will result in multiple calls to the upstream
# server, but they are cheap...
# The call to this function should normally be wrapped in a transaction,
# and this function itself will make no attempt to do anything about that.
def user_import(uid):
    u = user_search(userid=uid)
    if len(u) != 1:
        raise Exception("Internal error, duplicate or no user found")

    u = u[0]

    if User.objects.filter(username=u['u']).exists():
        raise Exception("User already exists")

    u = User(
        username=u['u'],
        first_name=u['f'],
        last_name=u['l'],
        email=u['e'],
        password='[REDACTED]',
    )
    u.save()

    auth_user_created_from_upstream.send(sender=user_import, user=u)

    return u

from django.db.models import Prefetch, QuerySet
from django.http import (
    HttpResponse,
)
from django.shortcuts import get_object_or_404

import json
from datetime import date, datetime, timedelta, timezone

from .models import (
    CommitFest,
    MailThread,
    Patch,
    PatchOnCommitFest,
)


def datetime_serializer(obj):
    # datetime must be checked before date, since datetime is a subclass of date
    if isinstance(obj, datetime):
        return obj.replace(tzinfo=timezone.utc).isoformat()

    if isinstance(obj, date):
        return obj.isoformat()

    if hasattr(obj, "to_json"):
        return obj.to_json()

    if isinstance(obj, QuerySet):
        return list(obj)

    raise TypeError(f"Type {type(obj)} not serializable to JSON")


def api_response(payload, status=200, content_type="application/json"):
    response = HttpResponse(
        json.dumps(payload, default=datetime_serializer), status=status
    )
    response["Content-Type"] = content_type
    response["Access-Control-Allow-Origin"] = "*"
    return response


def all_commitfests(request):
    """Return all commitfests, including closed ones."""
    return api_response({"commitfests": CommitFest.objects.order_by("id")})


def commitfestst_that_need_ci(request):
    cfs = CommitFest.relevant_commitfests()

    # We continue to run CI on the previous commitfest for a week after it ends
    # to give people some time to move patches over to the next one.
    if cfs["previous"].enddate <= datetime.now(timezone.utc).date() - timedelta(days=7):
        del cfs["previous"]

    del cfs["next_open"]
    del cfs["final"]

    return api_response({"commitfests": cfs})


def commitfest_patches(request, cfid):
    """Return all patches for a commitfest.

    This endpoint provides the data that cfbot previously scraped from the
    commitfest HTML page.

    Threads for every patch can be included with ?include=threads. Unknown
    tokens are ignored.
    """
    cf = get_object_or_404(CommitFest, pk=cfid)

    include = {i.strip() for i in request.GET.get("include", "").split(",")}
    include_threads = "threads" in include

    pocs = (
        PatchOnCommitFest.objects.filter(commitfest=cf)
        .select_related("patch")
        .prefetch_related("patch__authors")
        .order_by("patch__id")
    )

    if include_threads:
        pocs = pocs.prefetch_related(
            Prefetch(
                "patch__mailthread_set",
                queryset=MailThread.objects.with_has_attachment(),
            )
        )

    patches = []
    for poc in pocs:
        entry = poc.to_json()
        if include_threads:
            entry["threads"] = poc.patch.mailthread_set.all()
        patches.append(entry)

    return api_response(
        {
            "commitfest_id": cf.id,
            "patches": patches,
        }
    )


def patch_threads(request, patch_id):
    """Return thread information for a patch.

    This endpoint provides the data that cfbot previously scraped from the
    patch HTML page to construct thread URLs.
    """
    patch = get_object_or_404(Patch, pk=patch_id)

    threads = patch.mailthread_set.with_has_attachment()

    return api_response(
        {
            "patch_id": patch.id,
            "name": patch.name,
            "threads": threads,
        }
    )

from django.db import models


class QueuedMail(models.Model):
    sender = models.EmailField(max_length=100, null=False, blank=False)
    receiver = models.EmailField(max_length=100, null=False, blank=False)
    # We store the raw MIME message, so if there are any attachments or
    # anything, we just push them right in there!
    fullmsg = models.TextField(null=False, blank=False)

    def __str__(self):
        return "%s: %s -> %s" % (self.pk, self.sender, self.receiver)

from django.conf import settings
from django.contrib.auth.models import User
from django.db import models, transaction
from django.db.models import Exists, OuterRef, Q
from django.shortcuts import get_object_or_404

from datetime import datetime, timedelta, timezone

from pgcommitfest.mailqueue.util import send_template_mail
from pgcommitfest.userprofile.models import UserProfile

from .util import DiffableModel

# Patches with one of these tags are always moved to the next commitfest when
# their commitfest closes.
AUTO_MOVE_ALWAYS_TAG_NAMES = ["Bugfix"]


# We have few enough of these, and it's really the only thing we
# need to extend from the user model, so just create a separate
# class.
class Committer(models.Model):
    user = models.OneToOneField(
        User, null=False, blank=False, primary_key=True, on_delete=models.CASCADE
    )
    active = models.BooleanField(null=False, blank=False, default=True)

    def __str__(self):
        return str(self.user)

    @property
    def fullname(self):
        return "%s %s (%s)" % (
            self.user.first_name,
            self.user.last_name,
            self.user.username,
        )

    class Meta:
        ordering = ("user__last_name", "user__first_name")


class CommitFest(models.Model):
    STATUS_OPEN = 2
    STATUS_INPROGRESS = 3
    STATUS_CLOSED = 4
    _STATUS_CHOICES = (
        (STATUS_OPEN, "Open"),
        (STATUS_INPROGRESS, "In Progress"),
        (STATUS_CLOSED, "Closed"),
    )
    _STATUS_LABELS = (
        (STATUS_OPEN, "info"),
        (STATUS_INPROGRESS, "success"),
        (STATUS_CLOSED, "danger"),
    )
    name = models.CharField(max_length=100, blank=False, null=False, unique=True)
    status = models.IntegerField(
        null=False, blank=False, default=2, choices=_STATUS_CHOICES
    )
    startdate = models.DateField(blank=False, null=False)
    enddate = models.DateField(blank=False, null=False)
    draft = models.BooleanField(blank=False, null=False, default=False)

    @property
    def statusstring(self):
        return [v for k, v in self._STATUS_CHOICES if k == self.status][0]

    @property
    def periodstring(self):
        return "{0} – {1}".format(self.startdate, self.enddate)

    @property
    def last_open_date(self):
        return self.startdate - timedelta(days=1)

    @property
    def dev_cycle(self) -> int:
        if self.startdate.month in [1, 3]:
            return self.startdate.year - 2007
        else:
            return self.startdate.year - 2006

    @property
    def title(self):
        return "Commitfest %s" % self.name

    @property
    def is_closed(self):
        return self.status == self.STATUS_CLOSED

    @property
    def is_open(self):
        return self.status == self.STATUS_OPEN

    @property
    def is_open_regular(self):
        return self.is_open and not self.draft

    @property
    def is_open_draft(self):
        return self.is_open and self.draft

    @property
    def is_in_progress(self):
        return self.status == self.STATUS_INPROGRESS

    def to_json(self):
        return {
            "id": self.id,
            "name": self.name,
            "status": self.statusstring,
            "draft": self.draft,
            "startdate": self.startdate.isoformat(),
            "enddate": self.enddate.isoformat(),
        }

    def _should_auto_move_patch(self, patch, current_date):
        """Determine if a patch should be automatically moved to the next commitfest.

        A patch tagged as a bug fix is always moved, so that it doesn't get
        lost in a closed commitfest. Any other patch qualifies for auto-move
        if it both:
        1. Has had email activity within the configured number of days
        2. Hasn't been failing CI for longer than the configured threshold
        """
        if any(tag.name in AUTO_MOVE_ALWAYS_TAG_NAMES for tag in patch.tags.all()):
            return True

        activity_cutoff = current_date - timedelta(
            days=settings.AUTO_MOVE_EMAIL_ACTIVITY_DAYS
        )
        failing_cutoff = current_date - timedelta(
            days=settings.AUTO_MOVE_MAX_FAILING_DAYS
        )

        # Check for recent email activity
        if not patch.lastmail or patch.lastmail < activity_cutoff:
            return False

        # Check if CI has been failing too long
        try:
            cfbot_branch = patch.cfbot_branch
            if (
                cfbot_branch.failing_since
                and cfbot_branch.failing_since < failing_cutoff
            ):
                return False
        except CfbotBranch.DoesNotExist:
            # IF no CFBot data exists, the patch is probably very new (i.e. no
            # CI run has ever taken place for it yet). So we auto-move it in
            # that case.
            pass

        return True

    def auto_move_active_patches(self):
        """Automatically move active patches to the next commitfest.

        A patch is moved if it is tagged as a bug fix, or if it has recent
        email activity and hasn't been failing CI for too long.
        """
        current_date = datetime.now()

        # Get the next open commitfest (must exist, raises IndexError otherwise)
        # For draft CFs, find the next draft CF
        # For regular CFs, find the next regular CF by start date
        if self.draft:
            next_cf = CommitFest.objects.filter(
                status=CommitFest.STATUS_OPEN,
                draft=True,
                startdate__gt=self.enddate,
            ).order_by("startdate")[0]
        else:
            next_cf = CommitFest.objects.filter(
                status=CommitFest.STATUS_OPEN,
                draft=False,
                startdate__gt=self.enddate,
            ).order_by("startdate")[0]

        # Get all patches with open status in this commitfest
        open_pocs = (
            self.patchoncommitfest_set.filter(
                status__in=PatchOnCommitFest.OPEN_STATUSES
            )
            .select_related("patch")
            .prefetch_related("patch__tags")
        )

        for poc in open_pocs:
            if self._should_auto_move_patch(poc.patch, current_date):
                poc.patch.move(self, next_cf, by_user=None, by_cfbot=True)

    def send_closure_notifications(self):
        """Send email notifications to authors of patches that are still open."""
        # Get patches that still need action (not moved, not closed)
        open_pocs = list(
            self.patchoncommitfest_set.filter(
                status__in=PatchOnCommitFest.OPEN_STATUSES
            )
            .select_related("patch")
            .prefetch_related("patch__authors")
        )

        if not open_pocs:
            return

        # Collect unique authors and their patches
        authors_patches = {}
        for poc in open_pocs:
            for author in poc.patch.authors.all():
                if author not in authors_patches:
                    authors_patches[author] = []
                authors_patches[author].append(poc)

        # Send email to each author who has notifications enabled
        for author, patches in authors_patches.items():
            try:
                profile = author.userprofile
                if not profile.notify_all_author:
                    continue
                notifyemail = profile.notifyemail
            except UserProfile.DoesNotExist:
                # No profile means use default (notify=True), so continue
                notifyemail = None

            email = notifyemail.email if notifyemail else author.email

            send_template_mail(
                settings.NOTIFICATION_FROM,
                None,
                email,
                f"Commitfest {self.name} has closed and you have unmoved patches",
                "mail/commitfest_closure.txt",
                {
                    "user": author,
                    "commitfest": self,
                    "patches": patches,
                },
            )

    @staticmethod
    def _are_relevant_commitfests_up_to_date(cfs, current_date):
        inprogress_cf = cfs["in_progress"]

        if inprogress_cf and inprogress_cf.enddate < current_date:
            return False

        if cfs["open"].startdate <= current_date:
            return False

        if not cfs["draft"] or cfs["draft"].enddate < current_date:
            return False

        return True

    @classmethod
    def _refresh_relevant_commitfests(cls, for_update):
        cfs = CommitFest.relevant_commitfests(for_update=for_update, refresh=False)
        current_date = datetime.now(timezone.utc).date()

        if cls._are_relevant_commitfests_up_to_date(cfs, current_date):
            return cfs

        with transaction.atomic():
            cfs = CommitFest.relevant_commitfests(for_update=True, refresh=False)
            if cls._are_relevant_commitfests_up_to_date(cfs, current_date):
                # Some other request has already updated the commitfests, so we
                # return the new version
                return cfs

            inprogress_cf = cfs["in_progress"]
            if inprogress_cf and inprogress_cf.enddate < current_date:
                inprogress_cf.status = CommitFest.STATUS_CLOSED
                inprogress_cf.save()
                inprogress_cf.auto_move_active_patches()
                inprogress_cf.send_closure_notifications()

            open_cf = cfs["open"]

            if open_cf.startdate <= current_date:
                if open_cf.enddate < current_date:
                    open_cf.status = CommitFest.STATUS_CLOSED
                    open_cf.save()
                    cls.next_open_cf(current_date).save()
                    open_cf.auto_move_active_patches()
                    open_cf.send_closure_notifications()
                else:
                    open_cf.status = CommitFest.STATUS_INPROGRESS
                    open_cf.save()
                    cls.next_open_cf(current_date).save()

            draft_cf = cfs["draft"]
            if not draft_cf:
                cls.next_draft_cf(current_date).save()
            elif draft_cf.enddate < current_date:
                # Create next CF first so auto_move has somewhere to move patches
                draft_cf.status = CommitFest.STATUS_CLOSED
                draft_cf.save()
                cls.next_draft_cf(current_date).save()
                draft_cf.auto_move_active_patches()
                draft_cf.send_closure_notifications()

            return cls.relevant_commitfests(for_update=for_update)

    @classmethod
    def relevant_commitfests(cls, for_update=False, refresh=True):
        """If refresh is True (which is the default) this will automatically
        update the commitfests if their state is out of date. It will also
        create a new ones automatically when needed.

        The primary reason this refreshing is not done through a cron job is
        that that requires work on the infrastructure side. Which is a huge
        hassle to make happen in practice, due to an overloaded infrastructure
        team.

        Luckily checking if a refresh is needed is very cheap, just a few
        comparisons (see _are_relevant_commitfests_up_to_date for details). And
        the actual updates only happen ~once a month.
        """
        if refresh and settings.AUTO_CREATE_COMMITFESTS:
            return cls._refresh_relevant_commitfests(for_update=for_update)

        query_base = CommitFest.objects.order_by("-enddate")
        if for_update:
            query_base = query_base.select_for_update(no_key=True)
        last_three_commitfests = query_base.filter(draft=False)[:3]

        cfs = {}
        cfs["open"] = last_three_commitfests[0]

        if last_three_commitfests[1].status == CommitFest.STATUS_INPROGRESS:
            cfs["in_progress"] = last_three_commitfests[1]
            cfs["previous"] = last_three_commitfests[2]

        else:
            cfs["in_progress"] = None
            cfs["previous"] = last_three_commitfests[1]
            if cfs["open"].startdate.month == 3:
                cfs["final"] = cfs["open"]

        if cfs["in_progress"] and cfs["in_progress"].startdate.month == 3:
            cfs["final"] = cfs["in_progress"]
        elif cfs["open"].startdate.month == 3:
            cfs["final"] = cfs["open"]
        else:
            cfs["final"] = cls.next_open_cf(
                datetime(year=cfs["open"].dev_cycle + 2007, month=2, day=1)
            )

        cfs["draft"] = query_base.filter(draft=True).order_by("-startdate").first()
        cfs["next_open"] = cls.next_open_cf(cfs["open"].enddate + timedelta(days=1))

        return cfs

    @staticmethod
    def next_open_cf(from_date):
        # We don't have a CF in december, so we don't need to worry about 12 mod 12 being 0
        cf_months = [7, 9, 11, 1, 3]
        next_open_cf_month = min(
            (month for month in cf_months if month > from_date.month), default=1
        )
        next_open_cf_year = from_date.year
        if next_open_cf_month == 1:
            next_open_cf_year += 1

        next_open_dev_cycle = next_open_cf_year - 2006
        if next_open_cf_month in [1, 3]:
            next_open_dev_cycle -= 1

        if next_open_cf_month == 3:
            name = f"PG{next_open_dev_cycle}-Final"
        else:
            cf_number = cf_months.index(next_open_cf_month) + 1
            name = f"PG{next_open_dev_cycle}-{cf_number}"
        start_date = datetime(
            year=next_open_cf_year, month=next_open_cf_month, day=1
        ).date()
        end_date = datetime(
            year=next_open_cf_year, month=next_open_cf_month + 1, day=1
        ).date() - timedelta(days=1)

        return CommitFest(
            name=name,
            status=CommitFest.STATUS_OPEN,
            startdate=start_date,
            enddate=end_date,
        )

    @staticmethod
    def next_draft_cf(start_date):
        dev_cycle = start_date.year - 2006
        if start_date.month < 3:
            dev_cycle -= 1

        end_year = dev_cycle + 2007

        name = f"PG{dev_cycle}-Drafts"
        end_date = datetime(year=end_year, month=3, day=1).date() - timedelta(days=1)

        return CommitFest(
            name=name,
            status=CommitFest.STATUS_OPEN,
            startdate=start_date,
            enddate=end_date,
            draft=True,
        )

    @classmethod
    def get_in_progress(cls):
        return cls.objects.filter(status=CommitFest.STATUS_INPROGRESS).first()

    @classmethod
    def get_open_regular(cls):
        return cls.objects.filter(status=CommitFest.STATUS_OPEN, draft=False).first()

    @classmethod
    def get_current(cls):
        # First try to get in-progress CommitFest
        current = cls.get_in_progress()
        if current:
            return current
        # If no in-progress, fall back to open regular CommitFest
        return cls.get_open_regular()

    def __str__(self):
        return self.name

    class Meta:
        verbose_name_plural = "Commitfests"
        ordering = ("-startdate",)


